INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('96r1yvif4yz25kwzkijzv96r1yv3gn86', '2026-Q3', 'Set/2026 (T3)', '2026-09-16T14:51'::timestamptz, 'Wagner Ferreira Nunes', 'wagner ferreira nunes', 'PHARUS', 'Gabriel Oliveira', 10.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Totalmente no caminho', 'Tenho clareza e estou executando com consistência', 'Transparência, seriedade e parceria no envolvimento do contexto e expectativas indo além de uma simples acessoria.', NULL, 'Apesar de ainda não ter percebido resultados e retornos concretos das estratégias, o nível de relacionamento e envolvimento do estrategista.', 'Estreitar os laços de parceria junto ao grupo num evento presencia, partilhar experiências e sentir de perto aquilo que estamos construindo.', 'Apesar de todos as excelentes iniciativas, em se transando da insegurança jurídica atual do país em que vivemos, para mitigar a ansiedade e preocupações futuras, apoio a promoção de um encontro, para estreitar o network em o grupo e os idealizadores do projeto em especial o Adrian.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '96r1yvif4yz25kwzkijzv96r1yv3gn86', 'cadastro 2026-T3 (respondente) (0 dias)', 'cadastro 2026-T3') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('yxa42egjn8x5zbzgowyxa42qt481t54q', '2026-Q3', 'Set/2026 (T3)', '2026-09-16T15:23'::timestamptz, 'Paulo Roberto Rui Arantes', 'paulo roberto rui arantes', 'PHARUS', 'Gabriel Oliveira', 10.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Já estou há um tempo no projeto e sei que trata-se de pessoas de boa índole, excelente conhecimento, atualizadas no mercado financeiro e que estão dispostas a auxiliar os clientes na busca de seus ideiais', NULL, 'Gabriel, meu assessor está sempre à disposição para me auxiliar e apresentar oportunidades de negócios/investimentos. A equipe toda é expert no que faz e me sinto seguro com essa parceria', 'A resposta mais coerente e rápida é se alguma forma conseguir analisar se o retorno que terei renovando por mais 5 anos supera o investimento. Entendo que essa não é uma conta exata nem mesmo precisa já que envolve uma série de detalhes. Quanto eu consegui fazer render meu dinheiro estando no Pharus versus quanto eu conseguiria não estando. Além disso, a parceria envolve esforços de ambos os lados e também é quase impossível saber em que medida eu e o Pharus (Gabriel) estamos nos empenhando em nossas respectivas obrigações. Da minha parte, embora queira muito fazer dar certo e atingir um nível de tranquilidade financeira o quanto antes, entendo que ainda não consigo ser tão consistente em seguir a "cartilha". Além disso, nem todas as oportunidades se encaixam com a minha realidade financeira e minha renda, fazendo com que haja alguns gaps entre o que eu deveria e o que eu consigo realizar.', 'até agora a experiência tem sido muito boa. Acredito que a oportunidades apresentadas são sempre escolhidas a dedo, diversificadas e consistentes o que torna as decisões muito mais tranquilas e seguras. Meu assessor, como disse, está sempre à disposição, tem muito conhecimento do que fala, sabe ouvir e adequar as possibilidades e conhecimentos da Quarta Via à minha realidade. Talvez fosse interessante, como sugestão aqui, termos alguma reunião onde outros estrategistas (especialistas em outras áreas de dentro da Quarta Via) pudessem se reunir pra pensarmos em possibilidades para cada caso específico da realidade de cada cliente. Embora o Gabriel seja excelente, acredito que uma mesa redonda com outros especialistas (leilão, IR, etc) poderia trazer bons insights. Falando em IR, talvez se tivessem alguma área que pudesse analisar o IR do cliente para que haja a certeza de que o que estou pagando é realmente o mínimo ou se existe alguma estratégia para diminuir o tombo (claro, analisando todas as hipóteses e consequências de cada situação)', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'yxa42egjn8x5zbzgowyxa42qt481t54q', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
